-- Expand the archive as a structured corpus, not as a flat list of famous events.
-- Every case carries the same fields used by current-event retrieval: actors,
-- archetypal roles, preconditions, triggers, mechanisms, outcomes, and caveats.
-- This is intentionally a curated seed. It makes the retrieval layer honest and
-- useful now while leaving room for a larger source-backed archive later.

create temporary table tether_case_context_updates (
  slug text primary key,
  actor_roles jsonb not null,
  persona_archetypes jsonb not null,
  preconditions jsonb not null,
  triggers jsonb not null,
  time_to_outcome_days integer
) on commit drop;

