update public.historical_cases as cases
set
  actor_roles = updates.actor_roles,
  persona_archetypes = updates.persona_archetypes,
  preconditions = updates.preconditions,
  triggers = updates.triggers,
  time_to_outcome_days = updates.time_to_outcome_days,
  metadata = coalesce(cases.metadata, '{}'::jsonb) || jsonb_build_object('context_seed', 'archetype-context-v1'),
  updated_at = timezone('utc', now())
from tether_case_context_updates as updates
where cases.slug = updates.slug;

create temporary table tether_archive_expansion_rows (
  slug text primary key,
  title text not null,
  summary text not null,
  year_label text,
  start_year integer,
  end_year integer,
  domain_slug text,
  event_type_slug text,
  actor_roles jsonb not null,
  persona_archetypes jsonb not null,
  preconditions jsonb not null,
  triggers jsonb not null,
  structural_summary text not null,
  outcome_summary text not null,
  disanalogy_notes text not null,
  time_to_outcome_days integer,
  source_quality_score numeric(4,3) not null,
  case_confidence_score numeric(4,3) not null,
  mechanism_slugs text[] not null,
  source_title text not null,
  source_url text not null,
  source_publisher text not null
) on commit drop;

insert into tether_archive_expansion_rows values
  ('congress-of-vienna', 'Congress of Vienna', 'European powers redesigned the post-Napoleonic order around managed balance, restoration, and negotiated restraint.', '1814-1815', 1814, 1815, 'geopolitics', 'strategic-competition', '["war-weary powers", "restoration coalition", "national movement"]', '["restorer", "threatened-king", "anointed-outsider"]', '["A major war has exhausted the old balance", "victors fear both revolution and renewed hegemony"]', '["Diplomats redesign borders and recognition rules", "a concert system substitutes managed balance for open conflict"]', 'A system shaken by a challenger attempts to restore order through a coalition that contains both the challenger and the coalition members.', 'The settlement created a durable period of great-power consultation, but it also suppressed national and liberal pressures that later re-emerged.', 'Modern institutions are more rule-dense and public, so legitimacy cannot be managed only by elite bargaining.', 3650, .86, .82, ARRAY['power-transition','rules-reset','institutional-hardening'], 'Congress of Vienna', 'https://en.wikipedia.org/wiki/Congress_of_Vienna', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('berlin-blockade', 'Berlin Blockade', 'The Soviet attempt to isolate West Berlin became an endurance contest solved through an airlift rather than direct military escalation.', '1948-1949', 1948, 1949, 'geopolitics', 'strategic-competition', '["occupying power", "airlift coalition", "divided city"]', '["threatened-king", "anointed-outsider", "court-insider"]', '["A contested territory has symbolic value beyond its material value", "each side doubts the others willingness to retreat"]', '["Access is cut to test resolve", "a logistical workaround turns brinkmanship into endurance"]', 'A strategic rival applies pressure through a chokepoint, while the target searches for an alternative route that changes the cost of escalation.', 'The blockade failed, the airlift preserved access, and the division hardened into a longer institutional rivalry.', 'Modern chokepoints may be financial or digital rather than geographic, and substitutes can be faster but less durable.', 330, .84, .8, ARRAY['rivalry-escalation','network-fragility','institutional-hardening'], 'Berlin Blockade', 'https://en.wikipedia.org/wiki/Berlin_Blockade', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('korean-war', 'Korean War', 'A local conflict became a major international war because a divided territory sat inside a wider contest between rival power systems.', '1950-1953', 1950, 1953, 'geopolitics', 'strategic-competition', '["divided state", "great-power patrons", "military broker"]', '["anointed-outsider", "threatened-king", "court-insider"]', '["A local division is embedded in a global rivalry", "security guarantees make de-escalation costly"]', '["A border offensive internationalizes the conflict", "direct and indirect forces create a stalemate"]', 'When a local dispute is nested inside a larger rivalry, each side can treat a regional move as a test of global credibility.', 'The war ended in an armistice rather than a decisive settlement, preserving the structural conflict while limiting its geographic spread.', 'Nuclear deterrence, economic interdependence, and modern media change escalation paths but not the credibility problem.', 1095, .84, .81, ARRAY['power-transition','rivalry-escalation','institutional-hardening'], 'Korean War', 'https://en.wikipedia.org/wiki/Korean_War', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('iranian-revolution-1979', 'Iranian Revolution', 'A centralized monarchy lost the ability to convert modernization and coercion into a credible legitimacy story.', '1978-1979', 1978, 1979, 'geopolitics', 'legitimacy-crisis', '["centralized monarchy", "religious movement", "urban protesters", "military broker"]', '["threatened-king", "anointed-outsider", "court-insider"]', '["Modernization outpaces political inclusion", "coercion cannot restore a credible legitimacy story"]', '["A public mourning cycle scales protest", "the security apparatus hesitates and the regime loses initiative"]', 'A regime appears stable until a shared moral narrative lets dispersed grievances coordinate and elite hesitation becomes visible.', 'The monarchy fell and a new revolutionary order consolidated, showing that regime collapse does not imply pluralist stabilization.', 'Information systems and geopolitical context differ, and modern crises may resolve through leadership change without full regime replacement.', 365, .84, .8, ARRAY['legitimacy-erosion','elite-fragmentation','rules-reset'], 'Iranian Revolution', 'https://en.wikipedia.org/wiki/Iranian_Revolution', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('indian-independence-and-partition', 'Indian Independence and Partition', 'The end of British rule combined a successful independence movement with a violent territorial partition between competing national projects.', '1947', 1947, 1947, 'geopolitics', 'legitimacy-crisis', '["colonial government", "independence movement", "communal brokers"]', '["threatened-king", "anointed-outsider", "restorer", "betrayer-within"]', '["Imperial authority is weakened by war and local mobilization", "competing national identities cannot share the same settlement"]', '["A transfer of power is accelerated", "institutional exit is paired with territorial partition"]', 'When an incumbent exits a legitimacy crisis, the transition can produce both liberation and a new boundary conflict if no shared center survives.', 'Independence succeeded, but partition created mass displacement, lasting disputes, and new state-building burdens.', 'The scale and communal dimension are distinctive; the useful parallel is the difficulty of sequencing exit, recognition, and institutional continuity.', 365, .87, .83, ARRAY['legitimacy-erosion','elite-fragmentation','rules-reset'], 'Indian Independence and Partition', 'https://en.wikipedia.org/wiki/Partition_of_India', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('thirty-years-war', 'Thirty Years War', 'Religious, dynastic, and great-power conflicts fused into a self-sustaining war across central Europe.', '1618-1648', 1618, 1648, 'geopolitics', 'strategic-competition', '["imperial center", "confessional coalitions", "foreign powers"]', '["threatened-king", "anointed-outsider", "court-insider"]', '["Religious and dynastic conflicts are inseparable", "external actors can profit from internal fragmentation"]', '["A local succession dispute activates alliance commitments", "war becomes self-sustaining through financing and reprisal"]', 'A local legitimacy dispute becomes a systemic conflict when external actors can repeatedly fund and exploit the fracture.', 'The war ended through a negotiated settlement that modified sovereignty rules but left much of the region devastated.', 'Modern conflicts have faster information and formal institutions, yet proxy dynamics can still make a local crisis durable.', 10950, .85, .8, ARRAY['rivalry-escalation','elite-fragmentation','institutional-hardening'], 'Thirty Years War', 'https://en.wikipedia.org/wiki/Thirty_Years%27_War', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('panic-of-1907', 'Panic of 1907', 'A trust-company failure revealed how a highly connected financial system could transmit a local loss into a national liquidity crisis.', '1907', 1907, 1907, 'business', 'resource-shock', '["leveraged banks", "industrial financiers", "central bank reformers"]', '["threatened-king", "exile-strategist", "restorer"]', '["Credit depends on a small number of trust relationships", "there is no credible lender of last resort"]', '["A failed trust exposes hidden leverage", "withdrawals spread through the financial network"]', 'When trust is concentrated and liquidity backstops are weak, a small failure can become a system-wide confidence event.', 'Private coordination contained the panic temporarily, while the longer-run response created stronger central banking capacity.', 'Modern regulation and deposit insurance change the response surface, but shadow leverage can recreate the same confidence cascade.', 180, .82, .78, ARRAY['network-fragility','scarcity-shock','rules-reset'], 'Panic of 1907', 'https://en.wikipedia.org/wiki/Panic_of_1907', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('great-depression', 'Great Depression', 'A market crash, debt contraction, banking failures, and policy error combined into a prolonged global economic breakdown.', '1929-1939', 1929, 1939, 'business', 'resource-shock', '["speculative market", "households", "central government", "banking system"]', '["wise-builder", "threatened-king", "restorer", "reluctant-messenger"]', '["Asset prices outrun cash flows", "debt and banking links transmit a local loss"]', '["A market crash destroys confidence", "policy hesitation lets contraction compound"]', 'A speculative boom becomes systemic when asset losses hit banks, households, and public institutions at the same time.', 'Output and employment collapsed, then recovery depended on large institutional and policy redesign rather than a simple return of confidence.', 'Modern automatic stabilizers and central banks reduce some risks, but leverage and policy delay remain recurring failure modes.', 3650, .9, .86, ARRAY['speculative-excess','network-fragility','institutional-hardening','rules-reset'], 'Great Depression', 'https://en.wikipedia.org/wiki/Great_Depression', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('global-financial-crisis-2008', 'Global Financial Crisis', 'A housing decline exposed opaque, correlated leverage and forced emergency action across the global financial system.', '2007-2009', 2007, 2009, 'business', 'resource-shock', '["leveraged banks", "homeowners", "central bank", "public regulator"]', '["threatened-king", "betrayer-within", "restorer"]', '["Risk is distributed through opaque instruments", "institutions trust ratings and liquidity more than underlying cash flows"]', '["A housing decline reveals correlated exposure", "a liquidity freeze forces emergency intervention"]', 'A seemingly diversified system can fail together when its participants share the same hidden exposure and depend on continuous liquidity.', 'Governments stabilized the system, but public trust and the regulatory settlement were permanently altered.', 'The financial instruments and policy tools differ by cycle; the strongest parallel is shared exposure hidden behind apparent diversification.', 730, .92, .88, ARRAY['network-fragility','speculative-excess','regulatory-backlash','rules-reset'], 'Global Financial Crisis', 'https://en.wikipedia.org/wiki/Global_financial_crisis', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('dot-com-bubble', 'Dot-com Bubble', 'Internet optimism drove capital toward companies whose narrative and valuation outran durable revenue, followed by a sharp repricing.', '1995-2001', 1995, 2001, 'business', 'platform-transition', '["venture capital", "internet startups", "public investors", "platform incumbents"]', '["anointed-outsider", "wise-builder", "threatened-king"]', '["A new technology creates genuine productivity promise", "capital markets reward narrative faster than durable revenue"]', '["Public listings turn growth into a status race", "rising rates or weak earnings break the story"]', 'A real platform transition can still produce a speculative excess when the story of future scale becomes a substitute for present economics.', 'Most speculative firms failed, but the underlying internet infrastructure and business models continued to expand.', 'Modern AI or frontier-tech cycles may have better revenue than the dot-com era, so the comparison should focus on financing behavior, not inevitable collapse.', 730, .86, .82, ARRAY['speculative-excess','platform-disintermediation','commercialization-wave'], 'Dot-com Bubble', 'https://en.wikipedia.org/wiki/Dot-com_bubble', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('microsoft-antitrust-case', 'Microsoft Antitrust Case', 'A dominant software platform faced antitrust action over bundling, distribution control, and the effect of network power on rivals.', '1998-2001', 1998, 2001, 'business', 'regulatory-crackdown', '["software incumbent", "platform challengers", "antitrust regulator"]', '["threatened-king", "anointed-outsider", "restorer"]', '["A platform controls a distribution layer used by rivals", "network effects make ordinary competition difficult"]', '["Bundling turns product strategy into a competition issue", "regulators consider structural and behavioral remedies"]', 'A platform can make adjacent products look inseparable from infrastructure, turning ordinary product integration into a governance question.', 'The case changed strategic behavior and legal expectations even though the most severe structural remedy was not ultimately imposed.', 'Digital markets now move faster and have more data-driven feedback loops, so remedies may need to target access and interoperability.', 3650, .86, .82, ARRAY['monopoly-consolidation','regulatory-backlash','gatekeeper-collapse'], 'United States v. Microsoft', 'https://en.wikipedia.org/wiki/United_States_v._Microsoft_Corp.', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('pullman-strike', 'Pullman Strike', 'A wage reduction in a company town became a national rail boycott when workers lacked a credible channel to contest the whole employment bargain.', '1894', 1894, 1894, 'business', 'labor-dispute', '["railroad employer", "industrial workers", "labor mediator", "federal government"]', '["threatened-king", "anointed-outsider", "restorer"]', '["A company town makes wages and living costs inseparable", "workers have limited bargaining channels"]', '["A wage reduction collides with fixed rents", "a boycott spreads beyond the original workplace"]', 'Labor conflict expands when an employer controls both wages and the surrounding necessities of life, making a narrow pay dispute feel like total dependence.', 'Federal intervention broke the strike, but the episode strengthened the case for labor reform and independent bargaining.', 'Modern workers have different legal and digital organizing tools, but concentrated dependency can still make a small change existential.', 180, .82, .78, ARRAY['labor-realignment','institutional-hardening','network-fragility'], 'Pullman Strike', 'https://en.wikipedia.org/wiki/Pullman_Strike', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('flint-sit-down-strike', 'Flint Sit-Down Strike', 'Auto workers occupied production sites and forced a powerful manufacturer to recognize collective bargaining.', '1936-1937', 1936, 1937, 'business', 'labor-dispute', '["auto corporation", "organized workers", "state mediator"]', '["threatened-king", "anointed-outsider", "restorer"]', '["Mass production creates concentrated worker leverage", "the employer controls recognition and workplace access"]', '["Workers occupy the production site", "public pressure forces recognition and negotiation"]', 'Workers gain leverage when they can interrupt a tightly coupled production system at its most valuable node.', 'Recognition of the union reset labor relations in the auto industry and became a template for industrial bargaining.', 'A modern distributed workforce may need different choke points than a factory occupation, but leverage still follows system dependence.', 50, .84, .81, ARRAY['labor-realignment','network-fragility','rules-reset'], 'Flint Sit-Down Strike', 'https://en.wikipedia.org/wiki/Flint_sit-down_strike', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('patco-air-traffic-controllers-strike', 'PATCO Air Traffic Controllers Strike', 'A strike by safety-critical public employees became a direct test of executive authority and the state response to labor leverage.', '1981', 1981, 1981, 'business', 'labor-dispute', '["public employer", "unionized controllers", "executive authority"]', '["threatened-king", "anointed-outsider", "restorer"]', '["A safety-critical workforce has specialized leverage", "the governing system treats a public strike as a sovereignty test"]', '["Contract talks fail and workers walk out", "the government chooses replacement over concession"]', 'When labor controls a critical public network, the employer may interpret bargaining as a test of command rather than a normal negotiation.', 'The strike was defeated through mass dismissal, weakening the union and altering bargaining expectations for the era.', 'The analogy should not assume every critical workforce strike ends in replacement; legal and technical substitutability matter.', 120, .81, .78, ARRAY['labor-realignment','institutional-hardening','rules-reset'], 'PATCO Strike', 'https://en.wikipedia.org/wiki/Professional_Air_Traffic_Controllers_Organization', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('1994-major-league-baseball-strike', '1994 Major League Baseball Strike', 'A fight over salary controls and revenue distribution cancelled the postseason and damaged trust between league and players.', '1994-1995', 1994, 1995, 'sports', 'labor-dispute', '["league owners", "players union", "fans and broadcasters"]', '["threatened-king", "anointed-outsider", "reluctant-messenger"]', '["Revenue distribution is contested after commercialization", "both sides believe the product can survive a shutdown"]', '["A salary-control proposal becomes a system-wide ultimatum", "the season is cancelled and trust collapses"]', 'A mature entertainment labor market can turn a revenue-sharing argument into a legitimacy crisis when both sides underestimate the audience cost.', 'The agreement eventually restored play, but attendance and public trust took years to recover.', 'Sports audiences now have more substitute entertainment, increasing the cost of prolonged stoppage and changing bargaining leverage.', 250, .82, .79, ARRAY['labor-realignment','reputation-contagion','commercialization-wave'], '1994-95 MLB Strike', 'https://en.wikipedia.org/wiki/1994%E2%80%9395_Major_League_Baseball_strike', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('2011-nfl-lockout', '2011 NFL Lockout', 'Owners and players fought over the architecture of a highly commercialized sports product before reaching a new collective agreement.', '2011', 2011, 2011, 'sports', 'labor-dispute', '["league owners", "players union", "media market"]', '["threatened-king", "anointed-outsider", "restorer"]', '["A mature sports product has high shared revenue", "the labor agreement is also a governance agreement"]', '["Owners lock out players during renegotiation", "legal and commercial pressure produce a new agreement"]', 'When the product is a shared spectacle, labor bargaining also decides who controls the rules, schedule, and distribution of future growth.', 'A new agreement preserved the season and reset revenue and labor rules without breaking the league.', 'The presence of guaranteed media revenue made the stoppage more survivable than in less centralized sports systems.', 150, .82, .79, ARRAY['labor-realignment','commercialization-wave','rules-reset'], '2011 NFL Lockout', 'https://en.wikipedia.org/wiki/2011_NFL_lockout', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('1980-us-olympic-boycott', '1980 US Olympic Boycott', 'A geopolitical conflict turned participation in a global sporting institution into a public signal of alignment and refusal.', '1980', 1980, 1980, 'sports', 'strategic-competition', '["hostile states", "olympic committee", "athletes"]', '["threatened-king", "anointed-outsider", "reluctant-messenger"]', '["A symbolic institution is embedded in geopolitical rivalry", "participation can be weaponized without direct war"]', '["An invasion turns attendance into a loyalty test", "states sacrifice the event to signal resolve"]', 'Institutions designed as neutral stages can become strategic theaters when their symbolic value exceeds their operational function.', 'The boycott imposed costs on athletes and organizers while confirming a broader cycle of reciprocal sporting sanctions.', 'The politics of modern events are more commercial and fragmented, so symbolic withdrawal may target sponsors, platforms, or broadcasts instead.', 180, .78, .75, ARRAY['rivalry-escalation','reputation-contagion','institutional-hardening'], '1980 Summer Olympics boycott', 'https://en.wikipedia.org/wiki/1980_Summer_Olympics_boycott', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('mtv-launch', 'MTV Launch', 'A specialized cable channel reorganized music discovery around continuous visual programming and a new gatekeeper relationship with youth audiences.', '1981', 1981, 1981, 'entertainment', 'distribution-shift', '["broadcast incumbent", "music labels", "new cable channel", "artists"]', '["threatened-king", "wise-builder", "anointed-outsider"]', '["A new channel can aggregate a valuable youth audience", "music promotion depends on a small number of gatekeepers"]', '["A specialized channel gains distribution", "visual packaging changes the economics of music discovery"]', 'A new intermediary can grow by turning a fragmented cultural product into a repeatable programming format that advertisers can buy.', 'MTV became a powerful discovery and branding channel, changing music promotion and artist image-making.', 'Streaming recommendation systems are more personalized and less centralized, so the modern parallel is platform-mediated discovery rather than one channel.', 1825, .8, .77, ARRAY['gatekeeper-collapse','distribution-rebundling','audience-fragmentation'], 'MTV', 'https://en.wikipedia.org/wiki/MTV', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('television-mass-adoption', 'Television Mass Adoption', 'Television moved from novelty to household infrastructure and rewrote advertising, politics, and shared public attention.', '1948-1960', 1948, 1960, 'entertainment', 'platform-transition', '["radio incumbent", "broadcast networks", "advertisers", "households"]', '["threatened-king", "wise-builder", "anointed-outsider"]', '["A new medium combines reach and spectacle", "advertisers are looking for a more measurable mass audience"]', '["Affordable receivers cross a household threshold", "programming and advertising standardize around the new medium"]', 'A medium becomes socially decisive when adoption, content supply, and commercial measurement reinforce one another.', 'Television became the dominant mass medium for decades, centralizing attention while creating new production and advertising industries.', 'Attention is now fragmented across platforms, so the parallel is a threshold effect in adoption and monetization, not a return to one broadcast center.', 7300, .86, .83, ARRAY['platform-disintermediation','commercialization-wave','audience-fragmentation'], 'Television in the United States', 'https://en.wikipedia.org/wiki/History_of_television', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('hollywood-blacklist', 'Hollywood Blacklist', 'Political panic and reputational fear turned employment in the film industry into a test of ideological loyalty.', '1947-1960', 1947, 1960, 'entertainment', 'scandal-cycle', '["studio system", "government investigators", "artists", "public audience"]', '["threatened-king", "reluctant-messenger", "betrayer-within"]', '["A political panic makes reputation a condition of employment", "institutions prioritize self-protection over due process"]', '["Investigations turn association into evidence", "firms enforce informal exclusion to protect access"]', 'Reputation contagion becomes institutional hardening when employers believe visible punishment is safer than independent judgment.', 'The blacklist damaged careers and constrained speech before gradually weakening under legal, cultural, and market pressure.', 'Digital reputational systems move faster and are more decentralized, so the relevant pattern is the incentive to over-correct under attention pressure.', 3650, .82, .78, ARRAY['reputation-contagion','institutional-hardening','legitimacy-erosion'], 'Hollywood blacklist', 'https://en.wikipedia.org/wiki/Hollywood_blacklist', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('harlem-renaissance', 'Harlem Renaissance', 'A concentrated creative movement built a new cultural center and changed how Black identity was represented, distributed, and valued.', '1918-1935', 1918, 1935, 'culture', 'cultural-revival', '["black artists", "publishing networks", "urban audience", "cultural gatekeepers"]', '["anointed-outsider", "wise-builder", "reluctant-messenger"]', '["Migration concentrates talent and audience", "new distribution channels make self-definition more visible"]', '["A cluster of creators builds an alternative cultural center", "mainstream institutions begin to copy and commercialize the signal"]', 'Cultural power can grow when a previously excluded community develops its own audience, institutions, and symbolic vocabulary.', 'The movement influenced literature, music, art, and later civil-rights consciousness even as commercial attention moved on.', 'Modern creator platforms lower distribution barriers but can also fragment the shared institutions that made the earlier movement durable.', 3650, .84, .8, ARRAY['audience-fragmentation','nostalgia-revival','gatekeeper-collapse'], 'Harlem Renaissance', 'https://en.wikipedia.org/wiki/Harlem_Renaissance', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('civil-rights-act-movement', 'Civil Rights Movement and the Civil Rights Act', 'Organized protest, public witness, and federal intervention challenged a legitimacy gap between law and lived reality.', '1954-1968', 1954, 1968, 'culture', 'legitimacy-crisis', '["segregated establishment", "civil rights movement", "federal government", "public witness"]', '["threatened-king", "anointed-outsider", "reluctant-messenger", "restorer"]', '["A legal order contradicts lived legitimacy", "organizers can turn local injustice into national visibility"]', '["Publicized violence changes the political cost of inaction", "federal institutions rewrite the rules of access"]', 'A legitimacy crisis becomes reformable when organizers make the gap between formal rules and lived practice impossible for the wider public to ignore.', 'Federal legislation changed formal rights and enforcement, while social and political conflict continued in new forms.', 'Current movements operate in faster media environments and against more complex institutional targets, so legal change may be less singular.', 3650, .9, .86, ARRAY['legitimacy-erosion','reputation-contagion','rules-reset'], 'Civil Rights Movement', 'https://en.wikipedia.org/wiki/Civil_Rights_Movement', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('1960s-counterculture', '1960s Counterculture', 'A youth movement challenged inherited institutions and styles, then watched its symbols become part of the commercial mainstream.', '1960-1975', 1960, 1975, 'culture', 'cultural-revival', '["establishment institutions", "youth movement", "media industry", "commercial adopters"]', '["threatened-king", "anointed-outsider", "wise-builder"]', '["Postwar affluence creates room for identity experimentation", "older norms are losing moral authority"]', '["A style and politics of refusal spread through music and media", "commerce absorbs the symbols it once opposed"]', 'Cultural opposition can lose its outsider status not only through defeat but through rapid commercialization and imitation.', 'The movement changed norms, music, fashion, and politics while becoming a source of marketable identity.', 'Online subcultures move much faster and may fragment before building durable institutions.', 3650, .81, .77, ARRAY['nostalgia-revival','commercialization-wave','audience-fragmentation'], 'Counterculture of the 1960s', 'https://en.wikipedia.org/wiki/Counterculture_of_the_1960s', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('internet-commercialization', 'Internet Commercialization', 'The internet moved from a research and public-network environment into a commercial platform layer that reorganized distribution and attention.', '1990s-2000s', 1990, 2009, 'technology', 'platform-transition', '["public network builders", "telecom incumbents", "software entrepreneurs", "early users"]', '["wise-builder", "anointed-outsider", "threatened-king"]', '["A general-purpose network has escaped its original institutional niche", "access costs are falling faster than governance rules adapt"]', '["Commercial access becomes broadly available", "private platforms build distribution on top of the open network"]', 'A general-purpose infrastructure becomes transformative when private intermediaries can turn open connectivity into repeatable consumer markets.', 'Commercial access created new industries while concentrating discovery, advertising, and identity in platform intermediaries.', 'The first commercial wave had fewer platform dependencies than today, so modern comparisons must track who owns access and data.', 7300, .9, .85, ARRAY['platform-disintermediation','commercialization-wave','gatekeeper-collapse'], 'Commercial Internet', 'https://en.wikipedia.org/wiki/History_of_the_Internet', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('personal-computer-revolution', 'Personal Computer Revolution', 'Computing power moved from centralized institutions toward individuals and small organizations, creating a new software and hardware ecosystem.', '1970s-1980s', 1970, 1989, 'technology', 'platform-transition', '["mainframe incumbent", "personal-computer builders", "software developers", "households"]', '["threatened-king", "anointed-outsider", "wise-builder"]', '["Computing power can be miniaturized", "software makes hardware useful outside specialist institutions"]', '["Affordable machines reach enthusiasts and small firms", "an ecosystem forms around a new user-controlled platform"]', 'A platform transition accelerates when a capability becomes cheap and legible enough for users outside the incumbent institution to build around it.', 'Personal computing created durable software markets and changed organizational and household practices.', 'Current platform transitions may be dominated by cloud infrastructure rather than user-owned hardware, reversing some of the decentralization.', 7300, .87, .83, ARRAY['platform-disintermediation','commercialization-wave','gatekeeper-collapse'], 'History of personal computers', 'https://en.wikipedia.org/wiki/History_of_personal_computers', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('smartphone-platform-shift', 'Smartphone Platform Shift', 'Integrated smartphones combined computing, connectivity, sensors, and distribution into a new platform that reorganized everyday behavior.', '2007-2015', 2007, 2015, 'technology', 'platform-transition', '["mobile incumbents", "integrated platform builder", "app developers", "users"]', '["threatened-king", "wise-builder", "anointed-outsider"]', '["Mobile connectivity is widespread but fragmented", "a new interface can bundle hardware, software, and distribution"]', '["A compelling device resets user expectations", "developers and users converge on a new platform"]', 'Platform power compounds when one product integrates a previously fragmented stack and gives developers a new route to users.', 'Smartphones became the primary computing interface for billions and shifted value toward operating systems, app stores, and data-rich intermediaries.', 'The adoption curve is unusually fast and global; not every new technology can reproduce this network effect.', 3650, .9, .86, ARRAY['platform-disintermediation','distribution-rebundling','commercialization-wave'], 'Smartphone', 'https://en.wikipedia.org/wiki/Smartphone', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('montreal-protocol', 'Montreal Protocol', 'Scientific evidence and coordinated policy produced a global phase-out of ozone-depleting substances through a negotiated rules reset.', '1987', 1987, 1987, 'science', 'regulatory-crackdown', '["chemical producers", "scientific community", "national regulators", "multilateral broker"]', '["reluctant-messenger", "restorer", "wise-builder"]', '["A diffuse externality is scientifically legible", "producers can switch to substitutes if rules are coordinated"]', '["New evidence makes inaction politically costly", "states agree to phase out the harmful input"]', 'A global externality is governable when evidence, substitution paths, and an institution capable of phased coordination appear together.', 'The treaty became a durable model for science-informed international environmental governance.', 'The issue had a relatively clear substitute path; climate and biodiversity problems are more distributed and politically contested.', 3650, .91, .87, ARRAY['rules-reset','regulatory-backlash','network-fragility'], 'Montreal Protocol', 'https://en.wikipedia.org/wiki/Montreal_Protocol', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('manhattan-project', 'Manhattan Project', 'A wartime state centralized scientific talent, industrial capacity, and secrecy to create a strategic technology on an accelerated timeline.', '1942-1945', 1942, 1945, 'science', 'platform-transition', '["state research system", "scientists", "military planners", "industrial contractors"]', '["wise-builder", "exile-strategist", "threatened-king"]', '["A war creates extreme incentives for accelerated research", "the state can centralize talent and resources"]', '["A rival threat turns a research question into a crash program", "secrecy and scale produce a new strategic capability"]', 'A crisis can compress a long research cycle when a central sponsor aligns talent, money, procurement, and a single decisive objective.', 'The project succeeded technically and permanently changed strategic politics, while creating governance dilemmas around destructive capability.', 'Most contemporary innovation is more distributed and commercial, so state centralization may be an exception rather than a default.', 1460, .91, .88, ARRAY['frontier-privatization','commercialization-wave','institutional-hardening'], 'Manhattan Project', 'https://en.wikipedia.org/wiki/Manhattan_Project', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('apollo-program', 'Apollo Program', 'A geopolitical prestige contest became a systems project that coordinated science, industry, procurement, and public narrative around a visible goal.', '1961-1972', 1961, 1972, 'science', 'strategic-competition', '["national space agency", "rival state", "industrial contractors", "public audience"]', '["wise-builder", "anointed-outsider", "threatened-king"]', '["Scientific prestige is a proxy for national capability", "public funding can coordinate a complex supply chain"]', '["A rival achievement creates a deadline", "the state turns symbolic competition into a systems project"]', 'A symbolic rivalry can mobilize institutions when the goal is concrete enough to coordinate many specialized actors.', 'The United States achieved the landing goal and created durable technical and organizational capabilities, though the funding model later contracted.', 'Current prestige races are often private-public and software-driven, with less centralized control over the narrative.', 3650, .88, .84, ARRAY['power-transition','commercialization-wave','frontier-privatization'], 'Apollo program', 'https://en.wikipedia.org/wiki/Apollo_program', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('covid-19-vaccine-race', 'COVID-19 Vaccine Race', 'A global health emergency compressed research, manufacturing, procurement, and regulatory timelines through unprecedented coordination and conflict.', '2020-2021', 2020, 2021, 'science', 'platform-transition', '["public health agencies", "pharmaceutical firms", "research consortia", "global public"]', '["wise-builder", "exile-strategist", "reluctant-messenger", "restorer"]', '["A global threat creates shared urgency", "research, manufacturing, and procurement bottlenecks are interdependent"]', '["Emergency funding compresses development timelines", "public-private coordination scales production under uncertainty"]', 'A crisis turns scientific infrastructure into a strategic bottleneck and rewards actors who can coordinate discovery, production, and distribution at once.', 'Vaccines were developed and deployed rapidly, but access inequality, public trust, and platform ownership remained contested.', 'The pathogen, technology, and policy environment are specific; the general parallel is accelerated coordination under uncertainty.', 730, .9, .84, ARRAY['network-fragility','frontier-privatization','rules-reset'], 'COVID-19 vaccine development', 'https://en.wikipedia.org/wiki/COVID-19_vaccine', 'Encyclopaedia Britannica / Wikipedia reference'),
  ('hubble-space-telescope', 'Hubble Space Telescope Repair', 'A highly visible scientific project suffered a public failure, then rebuilt trust through transparent diagnosis, engineering repair, and shared ownership.', '1990-1993', 1990, 1993, 'science', 'scandal-cycle', '["scientific institution", "engineering team", "public audience", "repair coalition"]', '["wise-builder", "betrayer-within", "restorer"]', '["A flagship project carries high symbolic expectations", "complex systems hide failure modes across organizations"]', '["A visible defect undermines trust", "transparent diagnosis and repair restore the project"]', 'Visible failure does not always end an institution; a repair coalition can turn embarrassment into a credibility reset if the problem is legible and fixable.', 'The telescope was repaired and became one of the most trusted and productive scientific instruments in public life.', 'The repair was unusually visible and technically bounded; many institutional failures lack such a clear fix.', 1095, .87, .82, ARRAY['reputation-contagion','rules-reset','institutional-hardening'], 'Hubble Space Telescope', 'https://en.wikipedia.org/wiki/Hubble_Space_Telescope', 'Encyclopaedia Britannica / Wikipedia reference');

insert into public.historical_cases (
  slug, title, summary, year_label, start_year, end_year, domain_slug, event_type_slug,
  actor_roles, persona_archetypes, preconditions, triggers, structural_summary,
  outcome_summary, disanalogy_notes, time_to_outcome_days, source_quality_score,
  case_confidence_score, metadata
)
select
  slug, title, summary, year_label, start_year, end_year, domain_slug, event_type_slug,
  actor_roles, persona_archetypes, preconditions, triggers, structural_summary,
  outcome_summary, disanalogy_notes, time_to_outcome_days, source_quality_score,
  case_confidence_score,
  jsonb_build_object('seed', 'archive-expansion-v1', 'archive_scope', 'structured-corpus', 'source_pack', 'reference-canon')
from tether_archive_expansion_rows
on conflict (slug) do update
set
  title = excluded.title,
  summary = excluded.summary,
  year_label = excluded.year_label,
  start_year = excluded.start_year,
  end_year = excluded.end_year,
  domain_slug = excluded.domain_slug,
  event_type_slug = excluded.event_type_slug,
  actor_roles = excluded.actor_roles,
  persona_archetypes = excluded.persona_archetypes,
  preconditions = excluded.preconditions,
  triggers = excluded.triggers,
  structural_summary = excluded.structural_summary,
  outcome_summary = excluded.outcome_summary,
  disanalogy_notes = excluded.disanalogy_notes,
  time_to_outcome_days = excluded.time_to_outcome_days,
  source_quality_score = excluded.source_quality_score,
  case_confidence_score = excluded.case_confidence_score,
  metadata = coalesce(public.historical_cases.metadata, '{}'::jsonb) || excluded.metadata,
  updated_at = timezone('utc', now());

insert into public.historical_case_mechanisms
  (historical_case_id, mechanism_slug, weight, is_primary, evidence_note)
select
  cases.id,
  mechanism_slug,
  case ordinal_position when 1 then 1.000 when 2 then .800 else .650 end,
  ordinal_position = 1,
  'Archive expansion seed: mechanism selected during structured case encoding.'
from tether_archive_expansion_rows as archive
join public.historical_cases as cases on cases.slug = archive.slug
cross join lateral unnest(archive.mechanism_slugs) with ordinality as mechanisms(mechanism_slug, ordinal_position)
on conflict (historical_case_id, mechanism_slug) do update
set
  weight = excluded.weight,
  is_primary = excluded.is_primary,
  evidence_note = excluded.evidence_note;

insert into public.historical_case_sources
  (historical_case_id, source_type, citation_title, citation_url, publisher, quality_score, notes, metadata)
select
  cases.id,
  'reference',
  archive.source_title,
  archive.source_url,
  archive.source_publisher,
  archive.source_quality_score,
  'Reference source for the structured archive seed. Use as a starting point for later source triangulation.',
  jsonb_build_object('seed', 'archive-expansion-v1', 'triangulation_status', 'single-reference')
from tether_archive_expansion_rows as archive
join public.historical_cases as cases on cases.slug = archive.slug
on conflict (historical_case_id, citation_url) where citation_url is not null do update
set
  citation_title = excluded.citation_title,
  publisher = excluded.publisher,
  quality_score = excluded.quality_score,
  notes = excluded.notes,
  metadata = coalesce(public.historical_case_sources.metadata, '{}'::jsonb) || excluded.metadata,
  updated_at = timezone('utc', now());

-- The retrieval service scans this full structured corpus. Keep the query path
-- cheap as it grows and make future source-backed ranking easier to add.
create index if not exists historical_cases_structured_lookup_idx
  on public.historical_cases (domain_slug, event_type_slug, case_confidence_score desc, source_quality_score desc);

create index if not exists historical_case_mechanisms_case_weight_idx
  on public.historical_case_mechanisms (historical_case_id, weight desc);
